const statusSchema = z.enum(['draft', 'revised', 'final']);
const entityStatusSchema = z.enum(['confirmed', 'proposed', 'uncertain', 'contradicted', 'retconned', 'archived']);
const entityTypeSchema = z.enum(['character', 'relationship', 'place', 'organization', 'world_rule', 'object', 'event', 'fact', 'clue', 'secret', 'plot_thread', 'retcon', 'author_note', 'open_question']);
const projectSchema = z.object({ id: z.string(), title: z.string(), author: z.string(), description: z.string(), updatedAt: z.string(), createdAt: z.string().optional(), wordCount: z.number(), openWarnings: z.number(), bibleProgress: z.number(), status: z.enum(['active', 'archived']).optional(), lastOpenedAt: z.string().nullable().optional() }).transform((value) => ({ ...value, lastOpenedAt: value.lastOpenedAt ?? undefined }));
const onboardingSchema = z.object({ projectId: z.string(), currentStep: z.enum(['project', 'lore', 'manuscript', 'summary', 'completed']), completedSteps: z.array(z.string()), skippedSteps: z.array(z.string()), language: z.string(), genre: z.string(), loreCrafterRunId: z.string().nullable().optional(), importId: z.string().nullable().optional(), updatedAt: z.string() }).transform((value) => ({ ...value, loreCrafterRunId: value.loreCrafterRunId ?? undefined, importId: value.importId ?? undefined }));
const bookSchema = z.object({ id: z.string(), projectId: z.string(), title: z.string(), volume: z.number(), createdAt: z.string().optional(), updatedAt: z.string().optional() });
const sceneSchema = z.object({ id: z.string(), chapterId: z.string(), title: z.string(), orderIndex: z.number(), content: z.string(), pov: z.string(), location: z.string(), storyTime: z.string(), status: statusSchema, goal: z.string(), notes: z.string(), isImplicit: z.boolean().optional(), createdAt: z.string().optional(), updatedAt: z.string().optional() });
const sceneVersionSchema = z.object({ id: z.string(), sceneId: z.string(), versionNumber: z.number(), content: z.string(), reason: z.enum(['manual', 'before_correction', 'before_ai_change', 'before_import', 'automatic_checkpoint']), createdAt: z.string(), scene: sceneSchema });
const editorPreferencesSchema = z.object({ fontFamily: z.enum(['serif', 'sans', 'typewriter']), fontSize: z.number(), lineHeight: z.number() });
const chapterSchema = z.object({ id: z.string(), bookId: z.string(), title: z.string(), orderIndex: z.number(), scenes: z.array(sceneSchema), createdAt: z.string().optional(), updatedAt: z.string().optional() });
const manuscriptImportSchema = z.object({ chapters: z.array(chapterSchema), scenes: z.array(sceneSchema), versions: z.array(sceneVersionSchema) });
const entitySchema = z.object({ id: z.string(), projectId: z.string(), name: z.string(), type: entityTypeSchema, description: z.string(), status: entityStatusSchema, confidence: z.number(), source: z.string(), chapter: z.string(), scene: z.string(), authorConfirmed: z.boolean(), updatedAt: z.string(), createdAt: z.string().optional(), tags: z.array(z.string()), origin: z.enum(['manual', 'bible_update', 'edited', 'lore_crafter']) });
const sourceSchema = z.object({ id: z.string(), projectId: z.string(), entityId: z.string().nullable().optional(), proposalId: z.string().nullable().optional(), chapterId: z.string().nullable().optional(), sceneId: z.string().nullable().optional(), sourceDocumentId: z.string().nullable().optional(), excerpt: z.string(), startOffset: z.number().nullable().optional(), endOffset: z.number().nullable().optional(), createdAt: z.string() }).transform((source) => ({ ...source, entityId: source.entityId ?? undefined, proposalId: source.proposalId ?? undefined, chapterId: source.chapterId ?? undefined, sceneId: source.sceneId ?? undefined, sourceDocumentId: source.sourceDocumentId ?? undefined, startOffset: source.startOffset ?? undefined, endOffset: source.endOffset ?? undefined }));
const projectSourceDocumentSchema = z.object({ id: z.string(), projectId: z.string(), sourceKind: z.enum(['lore_crafter', 'research', 'author_note', 'external_text']), title: z.string(), content: z.string(), contentHash: z.string(), originId: z.string().nullable().optional(), createdAt: z.string(), updatedAt: z.string() }).transform((value) => ({ ...value, originId: value.originId ?? undefined }));
const runSchema = z.object({ id: z.string(), projectId: z.string(), sceneId: z.string(), sceneUpdatedAt: z.string(), contentHash: z.string(), extractorId: z.string(), analyzedContent: z.string().nullable().optional(), status: z.enum(['pending', 'running', 'completed', 'failed', 'reviewed']), createdAt: z.string(), completedAt: z.string().nullable().optional(), errorMessage: z.string().nullable().optional() }).transform((run) => ({ ...run, analyzedContent: run.analyzedContent ?? '', completedAt: run.completedAt ?? undefined, errorMessage: run.errorMessage ?? undefined }));
const proposalSchema = z.object({ id: z.string(), runId: z.string(), projectId: z.string(), sceneId: z.string(), targetEntityId: z.string().nullable().optional(), proposalAction: z.enum(['create_entity', 'update_entity', 'add_source', 'mark_contradiction', 'create_open_question', 'create_author_note']), entityType: entityTypeSchema, candidateName: z.string(), candidateDescription: z.string(), candidateStatus: entityStatusSchema, confidence: z.number(), classification: z.enum(['observable_fact', 'interpretation', 'open_question', 'possible_contradiction', 'author_note']), evidenceExcerpt: z.string(), startOffset: z.number().nullable().optional(), endOffset: z.number().nullable().optional(), reason: z.string(), reviewStatus: z.enum(['pending', 'accepted', 'edited', 'rejected']), reviewedAt: z.string().nullable().optional(), createdAt: z.string() }).transform((proposal) => ({ ...proposal, targetEntityId: proposal.targetEntityId ?? undefined, startOffset: proposal.startOffset ?? undefined, endOffset: proposal.endOffset ?? undefined, reviewedAt: proposal.reviewedAt ?? undefined }));
const workspaceSchema = z.object({ project: projectSchema, books: z.array(bookSchema), chapters: z.array(chapterSchema), entities: z.array(entitySchema) });
const loreSchema = z.object({ entityId: z.string(), projectId: z.string(), category: z.enum(['world_rule', 'history', 'objective_truth', 'belief', 'myth', 'mystery', 'terminology']), scope: z.enum(['series', 'book', 'arc']), revealState: z.enum(['author_only', 'foreshadowed', 'reader_revealed']), importance: z.enum(['core', 'supporting', 'background']), truthStatement: z.string(), rulesText: z.string(), exceptionsText: z.string(), authorKnowledge: z.string(), readerKnowledge: z.string(), revealPlan: z.string(), createdAt: z.string(), updatedAt: z.string() });
const loreCrafterAnalysisSchema = z.object({ understandingSummary: z.string(), confirmedStatements: z.array(z.string()), proposedWorldRules: z.array(z.string()), prerequisites: z.array(z.string()), effects: z.array(z.string()), limitations: z.array(z.string()), costs: z.array(z.string()), exceptions: z.array(z.string()), terminology: z.array(z.string()), relevantOrganizations: z.array(z.string()), relevantLocations: z.array(z.string()), historicalBackground: z.array(z.string()), unresolvedQuestions: z.array(z.string()), contradictions: z.array(z.string()), excludedContent: z.array(z.object({ content: z.string(), suggestedTarget: z.enum(['character_memory', 'plot_thread', 'continuity_state', 'manuscript', 'style']), reason: z.string() })), clarificationQuestions: z.array(z.string()), confidence: z.number(), warnings: z.array(z.string()) });
const loreCrafterRunSchema = z.object({ id: z.string(), projectId: z.string(), originalText: z.string(), contentHash: z.string(), providerId: z.string(), promptVersion: z.string(), status: z.enum(['pending', 'running', 'awaiting_review', 'completed', 'failed', 'cancelled']), understandingSummary: z.string().nullable().optional(), analysis: loreCrafterAnalysisSchema.nullable().optional(), confirmationText: z.string().nullable().optional(), createdAt: z.string(), updatedAt: z.string(), completedAt: z.string().nullable().optional(), errorCode: z.string().nullable().optional(), errorMessage: z.string().nullable().optional() }).transform((value) => ({ ...value, status: value.status as LoreCrafterRunStatus, understandingSummary: value.understandingSummary ?? undefined, analysis: value.analysis ?? undefined, confirmationText: value.confirmationText ?? undefined, completedAt: value.completedAt ?? undefined, errorCode: value.errorCode ?? undefined, errorMessage: value.errorMessage ?? undefined }));
const loreCrafterClarificationSchema = z.object({ id: z.string(), runId: z.string(), projectId: z.string(), question: z.string(), answer: z.string().nullable().optional(), status: z.enum(['open', 'answered', 'skipped']), createdAt: z.string(), updatedAt: z.string() }).transform((value) => ({ ...value, answer: value.answer ?? undefined }));
