const experienceSchema = z.object({ id: z.string(), projectId: z.string(), characterId: z.string(), eventEntityId: z.string().nullable().optional(), sceneId: z.string().nullable().optional(), title: z.string(), objectiveSummary: z.string(), subjectiveInterpretation: z.string(), emotionalImpact: z.string(), lastingEffect: z.string(), significance: z.string(), memoryReliability: z.string(), status: memoryStatusSchema, authorConfirmed: z.boolean(), createdAt: z.string(), updatedAt: z.string() }).transform((v) => ({ ...v, eventEntityId: v.eventEntityId ?? undefined, sceneId: v.sceneId ?? undefined }));
