const relationshipMemorySchema = z.object({ id: z.string(), projectId: z.string(), characterAId: z.string(), characterBId: z.string(), sceneId: z.string().nullable().optional(), memoryType: z.string(), title: z.string(), summary: z.string(), privateMeaning: z.string(), relationshipEffect: z.string(), significance: z.string(), status: memoryStatusSchema, authorConfirmed: z.boolean(), createdAt: z.string(), updatedAt: z.string() }).transform((v) => ({ ...v, sceneId: v.sceneId ?? undefined }));
const knowledgeSchema = z.object({ id: z.string(), projectId: z.string(), characterId: z.string(), factEntityId: z.string(), knowledgeState: z.string(), acquiredSceneId: z.string().nullable().optional(), changedSceneId: z.string().nullable().optional(), effectiveFromSceneId: z.string().nullable().optional(), effectiveUntilSceneId: z.string().nullable().optional(), sourceCharacterId: z.string().nullable().optional(), certainty: z.number(), notes: z.string(), status: memoryStatusSchema, authorConfirmed: z.boolean(), createdAt: z.string(), updatedAt: z.string() }).transform((v) => ({ ...v, acquiredSceneId: v.acquiredSceneId ?? undefined, changedSceneId: v.changedSceneId ?? undefined, effectiveFromSceneId: v.effectiveFromSceneId ?? undefined, effectiveUntilSceneId: v.effectiveUntilSceneId ?? undefined, sourceCharacterId: v.sourceCharacterId ?? undefined }));
const evidenceSchema = z.object({ id: z.string(), projectId: z.string(), memoryKind: z.string(), memoryId: z.string(), sourceReferenceId: z.string(), evidenceRole: z.string(), createdAt: z.string() });
const memoryRunSchema = z.object({ id: z.string(), projectId: z.string(), sceneId: z.string(), contentHash: z.string(), extractorId: z.string(), analyzedContent: z.string().optional(), status: z.enum(['pending', 'running', 'completed', 'failed', 'reviewed']), createdAt: z.string(), completedAt: z.string().nullable().optional(), errorMessage: z.string().nullable().optional() }).transform((v) => ({ ...v, completedAt: v.completedAt ?? undefined, errorMessage: v.errorMessage ?? undefined }));
const memoryProposalSchema = z.object({ id: z.string(), runId: z.string(), projectId: z.string(), sceneId: z.string(), proposalKind: z.string(), subjectCharacterId: z.string().nullable().optional(), relatedCharacterId: z.string().nullable().optional(), targetEntityId: z.string().nullable().optional(), payload: characterMemoryPayloadSchema, classification: z.string(), confidence: z.number(), evidenceExcerpt: z.string(), startOffset: z.number().nullable().optional(), endOffset: z.number().nullable().optional(), reason: z.string(), reviewStatus: z.enum(['pending', 'accepted', 'edited', 'rejected']), reviewedAt: z.string().nullable().optional(), analyzedContentHash: z.string().nullable().optional(), acceptedMemoryId: z.string().nullable().optional(), acceptedMemoryKind: z.string().nullable().optional(), createdAt: z.string() }).transform((v) => ({ ...v, payload: validateCharacterMemoryPayload(v.proposalKind, v.payload), subjectCharacterId: v.subjectCharacterId ?? undefined, relatedCharacterId: v.relatedCharacterId ?? undefined, targetEntityId: v.targetEntityId ?? undefined, startOffset: v.startOffset ?? undefined, endOffset: v.endOffset ?? undefined, reviewedAt: v.reviewedAt ?? undefined, analyzedContentHash: v.analyzedContentHash ?? undefined, acceptedMemoryId: v.acceptedMemoryId ?? undefined, acceptedMemoryKind: v.acceptedMemoryKind ?? undefined }));

function parse<TSchema extends z.ZodTypeAny>(schema: TSchema, value: unknown, label: string): z.infer<TSchema> {
  const result = schema.safeParse(value);
  if (!result.success) throw new Error(`${label} ist ungültig: ${result.error.issues.map((issue) => issue.message).join(', ')}`);
  return result.data;
}

function clone<T>(value: T): T { return JSON.parse(JSON.stringify(value)) as T; }
function syncManuscriptArtifact(state: BrowserState, artifactType: string, artifactId: string, status: ManuscriptAnalysisArtifactReviewStatus): void { const stamp = now(); state.manuscriptAnalysisArtifacts = (state.manuscriptAnalysisArtifacts ?? []).map((artifact) => artifact.artifactType === artifactType && artifact.artifactId === artifactId ? { ...artifact, reviewStatus: status, explicitlySkipped: false, updatedAt: stamp } : artifact); }
function now(): string { return new Date().toISOString(); }

function ledgerPosition(chapters: Chapter[], chapterId?: string, sceneId?: string, offset?: number): [number, number] {
  const chapter = chapters.find((item) => item.id === chapterId);
  const scene = chapter?.scenes.find((item) => item.id === sceneId);
  return [chapter?.orderIndex ?? Number.MIN_SAFE_INTEGER, (scene?.orderIndex ?? Number.MIN_SAFE_INTEGER) * 100000 + (offset ?? -1)];
}

function isLedgerEntryAtOrBefore(chapters: Chapter[], entry: ContinuityStateLedgerEntry, target: ManuscriptPosition): boolean {
  const entryPosition = ledgerPosition(chapters, entry.chapterId, entry.sceneId, entry.startOffset);
  const targetPosition = ledgerPosition(chapters, target.chapterId, target.sceneId, target.offset);
  return entryPosition[0] < targetPosition[0] || (entryPosition[0] === targetPosition[0] && entryPosition[1] <= targetPosition[1]);
}

function sameSource(source: StorySourceReference, input: CreateSourceReferenceInput): boolean {
  return source.projectId === input.projectId && source.entityId === input.entityId && source.chapterId === input.chapterId && source.sceneId === input.sceneId && source.excerpt === input.excerpt && source.startOffset === input.startOffset && source.endOffset === input.endOffset;
}

function addBrowserSource(state: BrowserState, input: CreateSourceReferenceInput): StorySourceReference {
  if (state.project.id !== input.projectId) throw new Error('Die Quellenreferenz gehört nicht zum Projekt.');
  const chapter = state.chapters.find((item) => item.id === input.chapterId);
  if (!chapter || !chapter.scenes.some((scene) => scene.id === input.sceneId)) throw new Error('Kapitel und Szene der Quelle passen nicht zusammen.');
  if (input.entityId && !state.entities.some((entity) => entity.id === input.entityId && entity.projectId === input.projectId)) throw new Error('Die Quellenentität gehört nicht zum Projekt.');
  const existing = state.sources.find((source) => sameSource(source, input));
  if (existing) return existing;
  const source: StorySourceReference = { id: crypto.randomUUID(), ...input, createdAt: now() };
  state.sources.push(source);
  return source;
}

function applyBrowserProposalReview(state: BrowserState, input: ReviewBibleProposalInput): BibleProposal {
  const proposal = state.proposals.find((item) => item.id === input.proposalId);
  if (!proposal) throw new Error('Der Vorschlag wurde nicht gefunden.');
  if (proposal.reviewStatus !== 'pending') throw new Error('Dieser Vorschlag wurde bereits geprüft und kann nicht erneut geändert werden.');
  const decision = input.decision ?? (input.reviewStatus === 'edited' ? 'edit_accept' : input.reviewStatus === 'rejected' ? 'reject' : 'accept');
  if (decision === 'defer') return clone(proposal);
  const name = input.candidateName ?? proposal.candidateName;
  const description = input.candidateDescription ?? proposal.candidateDescription;
  const rejected = decision === 'reject' || input.reviewStatus === 'rejected';
  const contradiction = decision === 'mark_contradiction' || proposal.classification === 'possible_contradiction';
  const effectiveDecision = contradiction && decision === 'accept' ? 'mark_contradiction' : decision;
  let entity = proposal.targetEntityId ? state.entities.find((item) => item.id === proposal.targetEntityId) : undefined;
  if (!rejected) {
    if (effectiveDecision === 'keep_existing') {
      if (!entity) throw new Error('Der Vorschlag hat keinen Ziel-Eintrag.');
    } else {
      const uncertain = effectiveDecision === 'save_uncertain';
      const authorNote = effectiveDecision === 'save_author_note';
      const type: StoryEntity['type'] = authorNote ? 'author_note' : effectiveDecision === 'accept_retcon' ? 'retcon' : proposal.entityType;
      const status: StoryEntity['status'] = uncertain ? 'uncertain' : effectiveDecision === 'mark_contradiction' ? 'contradicted' : effectiveDecision === 'accept_retcon' ? 'retconned' : 'confirmed';
      const authorConfirmed = !uncertain && effectiveDecision !== 'mark_contradiction';
      const origin: StoryEntity['origin'] = ['edit_accept', 'accept_new_value', 'accept_retcon'].includes(effectiveDecision) ? 'edited' : 'bible_update';
      const chapter = state.chapters.find((item) => item.scenes.some((scene) => scene.id === proposal.sceneId));
      const scene = chapter?.scenes.find((item) => item.id === proposal.sceneId);
      if (effectiveDecision === 'mark_contradiction') {
        if (!entity) throw new Error('Der Widerspruch hat keinen Ziel-Eintrag.');
        entity = { ...entity, status: 'contradicted', updatedAt: now() };
        state.entities = state.entities.map((item) => item.id === entity!.id ? entity! : item);
      } else if (entity) {
        entity = proposal.proposalAction === 'add_source' && effectiveDecision === 'accept'
          ? { ...entity, status, authorConfirmed, origin, updatedAt: now() }
          : { ...entity, name, description, type, status, authorConfirmed, origin, updatedAt: now() };
        state.entities = state.entities.map((item) => item.id === entity!.id ? entity! : item);
      } else {
        entity = { id: crypto.randomUUID(), projectId: proposal.projectId, name, type, description, status, confidence: proposal.confidence, source: proposal.evidenceExcerpt, chapter: chapter?.title ?? '', scene: scene?.title ?? '', authorConfirmed, updatedAt: now(), createdAt: now(), tags: [], origin };
        state.entities = [entity, ...state.entities];
      }
    }
    const chapter = state.chapters.find((item) => item.scenes.some((scene) => scene.id === proposal.sceneId));
    const scene = chapter?.scenes.find((item) => item.id === proposal.sceneId);
    if (!entity || !chapter || !scene) throw new Error('Die Quelle des Vorschlags konnte nicht verknüpft werden.');
    addBrowserSource(state, { projectId: proposal.projectId, entityId: entity.id, proposalId: proposal.id, chapterId: chapter.id, sceneId: scene.id, excerpt: proposal.evidenceExcerpt, startOffset: proposal.startOffset, endOffset: proposal.endOffset });
  }
  const reviewed: BibleProposal = { ...proposal, targetEntityId: entity?.id ?? proposal.targetEntityId, candidateName: name, candidateDescription: description, candidateStatus: rejected ? proposal.candidateStatus : effectiveDecision === 'save_uncertain' ? 'uncertain' : effectiveDecision === 'save_author_note' || effectiveDecision === 'accept' || effectiveDecision === 'edit_accept' ? 'confirmed' : proposal.candidateStatus, reviewStatus: input.reviewStatus, reviewedAt: now() };
  state.proposals = state.proposals.map((item) => item.id === proposal.id ? reviewed : item);
  return reviewed;
}

function applyBrowserCharacterMemoryReview(state: BrowserState, input: ReviewCharacterMemoryProposalInput): CharacterMemoryProposal {
  const proposal = state.memoryProposals.find((item) => item.id === input.proposalId);
  if (!proposal) throw new Error('Character-Memory-Vorschlag nicht gefunden.');
  if (proposal.reviewStatus !== 'pending') throw new Error('Dieser Vorschlag wurde bereits geprüft.');
  const updatedPayload = input.payload ?? proposal.payload;
  validateCharacterMemoryPayload(proposal.proposalKind, updatedPayload);
  if (input.reviewStatus === 'rejected') {
    const rejected = { ...proposal, payload: updatedPayload, reviewStatus: 'rejected' as const, reviewedAt: now() };
    state.memoryProposals = state.memoryProposals.map((item) => item.id === proposal.id ? rejected : item);
    return rejected;
  }
  const chapter = state.chapters.find((item) => item.scenes.some((scene) => scene.id === proposal.sceneId));
  const scene = chapter?.scenes.find((item) => item.id === proposal.sceneId);
  if (!chapter || !scene) throw new Error('Die Evidence-Szene konnte nicht gefunden werden.');
  const source = addBrowserSource(state, { projectId: proposal.projectId, entityId: proposal.subjectCharacterId, proposalId: proposal.id, chapterId: chapter.id, sceneId: scene.id, excerpt: proposal.evidenceExcerpt, startOffset: proposal.startOffset, endOffset: proposal.endOffset });
  let memoryId = proposal.acceptedMemoryId;
  const memoryKind: CharacterMemoryProposal['proposalKind'] = proposal.proposalKind;
  const payload = updatedPayload as unknown as Record<string, unknown>;
  const stamp = now();
  const uncertain = input.decision === 'uncertain';
  const status = uncertain ? 'uncertain' as const : 'confirmed' as const;
  const authorConfirmed = !uncertain;
  if (!memoryId) memoryId = crypto.randomUUID();
  if (proposal.proposalKind === 'voice_pattern' && proposal.subjectCharacterId) {
    const existing = state.voicePatterns.find((item) => item.characterId === proposal.subjectCharacterId && item.patternType === payload.patternType && item.patternText.toLocaleLowerCase() === String(payload.patternText).toLocaleLowerCase() && item.relatedCharacterId === (payload.relatedCharacterId as string | undefined));
    const saved = existing ? { ...existing, occurrenceCount: existing.occurrenceCount + 1, status, authorConfirmed, updatedAt: stamp } : { id: memoryId, projectId: proposal.projectId, characterId: proposal.subjectCharacterId, relatedCharacterId: payload.relatedCharacterId as string | undefined, patternType: payload.patternType as CharacterVoicePattern['patternType'], patternText: String(payload.patternText), description: String(payload.description ?? ''), contextCondition: String(payload.contextCondition ?? ''), confidence: proposal.confidence, status, authorConfirmed, occurrenceCount: 1, createdAt: stamp, updatedAt: stamp };
    memoryId = saved.id; state.voicePatterns = [saved, ...state.voicePatterns.filter((item) => item.id !== saved.id)];
  } else if (proposal.proposalKind === 'experience' && proposal.subjectCharacterId) {
    const saved = { id: memoryId, projectId: proposal.projectId, characterId: proposal.subjectCharacterId, eventEntityId: payload.eventEntityId as string | undefined, sceneId: proposal.sceneId, title: String(payload.title), objectiveSummary: String(payload.objectiveSummary ?? ''), subjectiveInterpretation: String(payload.subjectiveInterpretation ?? ''), emotionalImpact: String(payload.emotionalImpact ?? ''), lastingEffect: String(payload.lastingEffect ?? ''), significance: payload.significance as CharacterExperience['significance'], memoryReliability: payload.memoryReliability as CharacterExperience['memoryReliability'], status, authorConfirmed, createdAt: stamp, updatedAt: stamp } satisfies CharacterExperience;
    state.experiences = [saved, ...state.experiences.filter((item) => item.id !== saved.id)];
  } else if (proposal.proposalKind === 'dialogue_memory' && proposal.subjectCharacterId) {
    const participants = (payload.participants as Array<{ characterId: string; role: DialogueMemoryParticipant['role'] }>).map((item) => ({ dialogueMemoryId: memoryId!, characterId: item.characterId, role: item.role }));
    const saved = { id: memoryId, projectId: proposal.projectId, speakerId: proposal.subjectCharacterId, sceneId: proposal.sceneId, dialogueKind: payload.dialogueKind as CharacterDialogueMemory['dialogueKind'], topic: String(payload.topic ?? ''), summary: String(payload.summary), exactExcerpt: String(payload.exactExcerpt ?? ''), emotionalTone: String(payload.emotionalTone ?? ''), hiddenIntent: String(payload.hiddenIntent ?? ''), significance: payload.significance as CharacterDialogueMemory['significance'], truthfulness: payload.truthfulness as CharacterDialogueMemory['truthfulness'], status, authorConfirmed, participants, createdAt: stamp, updatedAt: stamp } satisfies CharacterDialogueMemory;
    state.dialogueMemories = [saved, ...state.dialogueMemories.filter((item) => item.id !== saved.id)];
  } else if (proposal.proposalKind === 'relationship_memory' && proposal.subjectCharacterId) {
    const ids = [proposal.subjectCharacterId, String(payload.relatedCharacterId)].sort();
    const saved = { id: memoryId, projectId: proposal.projectId, characterAId: ids[0], characterBId: ids[1], sceneId: proposal.sceneId, memoryType: payload.memoryType as RelationshipMemory['memoryType'], title: String(payload.title), summary: String(payload.summary), privateMeaning: String(payload.privateMeaning ?? ''), relationshipEffect: String(payload.relationshipEffect ?? ''), significance: payload.significance as RelationshipMemory['significance'], status, authorConfirmed, createdAt: stamp, updatedAt: stamp } satisfies RelationshipMemory;
    state.relationshipMemories = [saved, ...state.relationshipMemories.filter((item) => item.id !== saved.id)];
  } else if (proposal.proposalKind === 'knowledge_change' && proposal.subjectCharacterId) {
    const saved = { id: memoryId, projectId: proposal.projectId, characterId: proposal.subjectCharacterId, factEntityId: String(payload.factEntityId), knowledgeState: payload.knowledgeState as CharacterKnowledgeState['knowledgeState'], acquiredSceneId: proposal.sceneId, changedSceneId: proposal.sceneId, sourceCharacterId: payload.sourceCharacterId as string | undefined, certainty: Number(payload.certainty), notes: String(payload.notes ?? ''), status, authorConfirmed, createdAt: stamp, updatedAt: stamp } satisfies CharacterKnowledgeState;
    const previous = state.knowledgeStates.find((item) => item.characterId === saved.characterId && item.factEntityId === saved.factEntityId);
    if (previous) state.knowledgeHistory = [...state.knowledgeHistory, previous];
    state.knowledgeStates = [saved, ...state.knowledgeStates.filter((item) => item.id !== saved.id && !(item.characterId === saved.characterId && item.factEntityId === saved.factEntityId))];
  } else {
    throw new Error('Dieser Vorschlagstyp benötigt eine manuelle Pflege.');
  }
  const evidence: CharacterMemoryEvidence = { id: crypto.randomUUID(), projectId: proposal.projectId, memoryKind: memoryKind as CharacterMemoryEvidence['memoryKind'], memoryId, sourceReferenceId: source.id, evidenceRole: 'primary', createdAt: stamp };
  state.memoryEvidence = [evidence, ...state.memoryEvidence.filter((item) => !(item.memoryKind === evidence.memoryKind && item.memoryId === evidence.memoryId && item.sourceReferenceId === evidence.sourceReferenceId))];
  const reviewed = { ...proposal, payload: updatedPayload, reviewStatus: input.reviewStatus, reviewedAt: stamp, acceptedMemoryId: memoryId, acceptedMemoryKind: memoryKind as CharacterMemoryProposal['acceptedMemoryKind'] };
  state.memoryProposals = state.memoryProposals.map((item) => item.id === proposal.id ? reviewed : item);
  return reviewed;
}

