  async createStoryEntity(input: CreateStoryEntityInput): Promise<StoryEntity> { const state = this.read(); const stamp = now(); if (state.project.id !== input.projectId) throw new Error('Die Entität gehört nicht zum Projekt.'); const chapter = state.chapters.find((item) => item.id === input.chapterId); const scene = chapter?.scenes.find((item) => item.id === input.sceneId); const saved: StoryEntity = { id: crypto.randomUUID(), projectId: input.projectId, name: input.name, type: input.type, description: input.description, status: input.status, confidence: input.confidence, source: input.excerpt, chapter: chapter?.title ?? '', scene: scene?.title ?? '', authorConfirmed: input.authorConfirmed, tags: input.tags, updatedAt: stamp, createdAt: stamp, origin: input.origin ?? 'manual' }; state.entities = [saved, ...state.entities]; if (chapter && scene && input.sceneId) addBrowserSource(state, { projectId: input.projectId, entityId: saved.id, chapterId: chapter.id, sceneId: input.sceneId, excerpt: input.excerpt }); this.write(state); return clone(saved); }
