  async createProjectSourceDocument(input: CreateProjectSourceDocumentInput): Promise<ProjectSourceDocument> { const state = this.read(); if (state.project.id !== input.projectId) throw new Error('Quelldokument gehört nicht zum Projekt.'); const old = (state.sourceDocuments ?? []).find((item) => item.projectId === input.projectId && item.sourceKind === input.sourceKind && item.contentHash === input.contentHash); if (old && old.content !== input.content) throw new Error('Ein unveränderliches Quelldokument mit diesem Hash enthält bereits anderen Text.'); const stamp = now(); const saved: ProjectSourceDocument = { ...input, id: old?.id ?? crypto.randomUUID(), createdAt: old?.createdAt ?? stamp, updatedAt: stamp }; state.sourceDocuments = [saved, ...(state.sourceDocuments ?? []).filter((item) => item.id !== saved.id)]; this.write(state); return clone(saved); }
  async listProjectSourceDocuments(projectId: string): Promise<ProjectSourceDocument[]> { return (this.read().sourceDocuments ?? []).filter((item) => item.projectId === projectId).map(clone); }
  async createProjectSourceReference(input: CreateProjectSourceReferenceInput): Promise<StorySourceReference> { const state = this.read(); const document = (state.sourceDocuments ?? []).find((item) => item.id === input.sourceDocumentId && item.projectId === input.projectId); if (!document) throw new Error('Quelldokument gehört nicht zum Projekt.'); const chars = Array.from(document.content); if (input.startOffset < 0 || input.endOffset <= input.startOffset || input.endOffset > chars.length || chars.slice(input.startOffset, input.endOffset).join('') !== input.excerpt) throw new Error('Projektquelle passt nicht zu Unicode-Positionen.'); const saved: StorySourceReference = { id: crypto.randomUUID(), projectId: input.projectId, entityId: input.entityId, proposalId: input.proposalId, sourceDocumentId: input.sourceDocumentId, excerpt: input.excerpt, startOffset: input.startOffset, endOffset: input.endOffset, createdAt: now() }; state.sources = [saved, ...state.sources]; this.write(state); return clone(saved); }
