  async saveCharacterKnowledgeState(input: SaveCharacterKnowledgeStateInput): Promise<CharacterKnowledgeState> {
    const state = this.read();
    if (!state.entities.some((x) => x.id === input.characterId && x.projectId === input.projectId && x.type === 'character')) throw new Error('Die Figur wurde nicht gefunden.');
    if (!state.entities.some((x) => x.id === input.factEntityId && x.projectId === input.projectId)) throw new Error('Der Fakt wurde nicht gefunden.');
    const stamp = now();
    const old = input.id ? state.knowledgeStates.find((x) => x.id === input.id) : undefined;
    const transitionSceneId = input.changedSceneId ?? input.acquiredSceneId;
    if (old && (old.knowledgeState !== input.knowledgeState || old.certainty !== input.certainty)) {
      state.knowledgeHistory.unshift({
        ...old,
        id: crypto.randomUUID(),
        effectiveFromSceneId: old.effectiveFromSceneId ?? old.changedSceneId ?? old.acquiredSceneId,
        effectiveUntilSceneId: transitionSceneId,
        updatedAt: stamp,
      });
    }
    const saved: CharacterKnowledgeState = {
      ...input,
      id: input.id ?? crypto.randomUUID(),
      effectiveFromSceneId: old ? transitionSceneId ?? old.effectiveFromSceneId : input.effectiveFromSceneId ?? transitionSceneId,
      effectiveUntilSceneId: undefined,
      createdAt: old?.createdAt ?? stamp,
      updatedAt: stamp,
    };
    state.knowledgeStates = [saved, ...state.knowledgeStates.filter((x) => x.id !== saved.id)];
    this.write(state);
    return clone(saved);
  }
